package com.klikli_dev.occultism.util;

import com.klikli_dev.occultism.Occultism;
import com.klikli_dev.occultism.api.common.data.GlobalBlockPos;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.LevelChunk.EntityCreationType;
import net.minecraft.world.level.storage.TagValueOutput;
import net.neoforged.neoforge.capabilities.BlockCapability;
import net.neoforged.neoforge.server.ServerLifecycleHooks;

public class BlockEntityUtil {
    public static boolean isLoaded(Level level, GlobalBlockPos pos) {
        if (pos == null)
            return false;

        if (level.dimension() == pos.getDimensionKey()) {
            return level.isLoaded(pos.getPos());
        }
        if (level.isClientSide()) //can only access other dimensions on the server.
            return false;

        Level dimensionWorld = ServerLifecycleHooks.getCurrentServer().getLevel(pos.getDimensionKey());
        if (dimensionWorld != null)
            return dimensionWorld.isLoaded(pos.getPos());

        return false;
    }

    /**
     * Gets the block entity from the given global position.
     *
     * @param level the level. Returns null if the dimension is unloaded.
     * @param pos   the global position.
     * @return the block entity or null.
     */
    public static BlockEntity get(Level level, GlobalBlockPos pos) {
        if (pos == null)
            return null;

        if (level.dimension() == pos.getDimensionKey()) {
            return getWorldTileEntityUnchecked(level, pos.getPos());
        }
        if (level.isClientSide()) //can only access other dimensions on the server.
            return null;

        Level dimensionWorld = ServerLifecycleHooks.getCurrentServer().getLevel(pos.getDimensionKey());
        if (dimensionWorld != null)
            return getWorldTileEntityUnchecked(dimensionWorld, pos.getPos());

        return null;
    }

    static BlockEntity getWorldTileEntityUnchecked(Level level, BlockPos pos) {
        if (!level.isLoaded(pos)) {
            return null;
        } else {
            return level.getChunkAt(pos).getBlockEntity(pos, EntityCreationType.IMMEDIATE);
        }
    }


    /**
     * Updates the block entity at the given position (mark dirty & send updates)
     *
     * @param level the level to update
     * @param pos   the position to update
     */
    public static void updateTile(Level level, BlockPos pos) {
        if (level == null || level.isClientSide() || !level.isLoaded(pos)) {
            return;
        }

        BlockState state = level.getBlockState(pos);
        level.sendBlockUpdated(pos, state, state, 2);
        level.blockEntityChanged(pos);
    }

    /**
     * Checks all faces of a block entity for the given capability.
     *
     * @param blockEntity the block entity to check.
     * @param capability  the capability to check for.
     * @return true if the capability is found on any face.
     */
    public static <T> boolean hasCapabilityOnAnySide(BlockEntity blockEntity, BlockCapability<T, Direction> capability) {
        for (Direction face : Direction.values()) {
            if (blockEntity.getLevel().getCapability(capability, blockEntity.getBlockPos(), blockEntity.getBlockState(), blockEntity, face) != null)
                return true;
        }
        return false;
    }

    /**
     * Handles the common use case of giving self as item with block entity nbt.
     *
     * @param block the current block.
     * @param level the level
     * @param pos   the position.
     */
    public static ItemStack getItemWithNbt(Block block, LevelReader level, BlockPos pos) {
        ItemStack itemStack = new ItemStack(block);
        BlockEntity blockEntity = level.getBlockEntity(pos);

        if (blockEntity != null) {
            // Get the block entity data and set it on the item stack
            var tag = blockEntity.saveWithoutMetadata(level.registryAccess());
            if (!tag.isEmpty()) {
                var output = TagValueOutput.createWithoutContext(
                        ProblemReporter.DISCARDING);
                BlockItem.setBlockEntityData(itemStack, blockEntity.getType(), output);
            }
        } else {
            Occultism.LOGGER.warn("BlockEntity is null for block {} at pos {}, cannot get ItemStack with Components", block, pos);
        }

        return itemStack;
    }
}

package com.klikli_dev.occultism.util;

import net.minecraft.tags.TagKey;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.transfer.ResourceHandler;
import net.neoforged.neoforge.transfer.ResourceHandlerUtil;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.item.ItemUtil;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import org.jetbrains.annotations.Nullable;

public final class ItemTransferUtil {

    private ItemTransferUtil() {
    }

    public static ItemStack insertItem(@Nullable ResourceHandler<ItemResource> handler, ItemStack stack, boolean simulate) {
        if (handler == null || stack.isEmpty()) {
            return stack;
        }

        return ItemUtil.insertItemReturnRemaining(handler, stack, simulate, null);
    }

    public static ItemStack insertItem(@Nullable ResourceHandler<ItemResource> handler, int index, ItemStack stack, boolean simulate) {
        if (handler == null || stack.isEmpty()) {
            return stack;
        }

        return ItemUtil.insertItemReturnRemaining(handler, index, stack, simulate, null);
    }

    public static ItemStack insertItemStacked(@Nullable ResourceHandler<ItemResource> handler, ItemStack stack, boolean simulate, @Nullable Transaction transaction) {
        if (handler == null || stack.isEmpty()) {
            return stack;
        }

        try (var tx = transaction == null ? Transaction.openRoot() : transaction) {
            int inserted = ResourceHandlerUtil.insertStacking(handler, ItemResource.of(stack), stack.getCount(), tx);
            if (!simulate) {
                tx.commit();
            }

            int remainder = stack.getCount() - inserted;
            return remainder <= 0 ? ItemStack.EMPTY : stack.copyWithCount(remainder);
        }
    }

    public static ItemStack insertItemStacked(@Nullable ResourceHandler<ItemResource> handler, ItemStack stack, boolean simulate) {
        return insertItemStacked(handler, stack, simulate, null);
    }

    public static int getFirstFilledSlot(ResourceHandler<ItemResource> handler) {
        for (int i = 0; i < handler.size(); i++) {
            if (!handler.getResource(i).isEmpty())
                return i;
        }
        return -1;
    }

    public static int getFirstMatchingSlot(ResourceHandler<ItemResource> handler, TagKey<Item> tag) {
        for (int i = 0; i < handler.size(); i++) {
            ItemResource resource = handler.getResource(i);
            if (!resource.isEmpty() && resource.toStack().is(tag)) {
                return i;
            }
        }
        return -1;
    }

    public static ItemStack extractItem(@Nullable ResourceHandler<ItemResource> handler, int index, int amount, boolean simulate) {

        if (handler == null || amount <= 0 || index < 0 || index >= handler.size()) {
            return ItemStack.EMPTY;
        }

        var resource = handler.getResource(index);
        if (resource.isEmpty()) {
            return ItemStack.EMPTY;
        }

        try (var tx = Transaction.openRoot()) {
            int extracted = handler.extract(index, resource, amount, tx);
            if (!simulate) {
                tx.commit();
            }

            return extracted <= 0 ? ItemStack.EMPTY : resource.toStack(extracted);
        }
    }

    public static ItemStack extractItem(@Nullable ResourceHandler<ItemResource> handler, ItemResource resource, int amount, boolean simulate) {
        if (handler == null || resource.isEmpty() || amount <= 0) {
            return ItemStack.EMPTY;
        }

        try (var tx = Transaction.openRoot()) {
            int extracted = handler.extract(resource, amount, tx);
            if (!simulate) {
                tx.commit();
            }

            return extracted <= 0 ? ItemStack.EMPTY : resource.toStack(extracted);
        }
    }

    public static void giveItemToPlayer(Player player, ItemStack stack, @Nullable Transaction transaction) {
        if (stack.isEmpty()) {
            return;
        }

        var handler = player.getCapability(Capabilities.Item.ENTITY);
        if (handler != null) {
            stack = insertItemStacked(handler, stack, false, transaction);
        }

        if (!stack.isEmpty()) {
            player.getInventory().placeItemBackInInventory(stack);
        }
    }

    public static void giveItemToPlayer(Player player, ItemStack stack) {
        giveItemToPlayer(player, stack, null);
    }
}

